// Deliberately simplified game process, not instructions for producing food.
export const DAIRY_STAGES=['warm','set','cut','stir','press','salt'];
export const PORTMANN_STORE={id:'portmann-store',x:15,z:-5,range:2.5,name:'Portmann-Store · Alpprodukte verkaufen',portmannStore:true};
export const freshDairy=()=>({active:null,batches:[],nextId:1,sold:0});
const fail=message=>({ok:false,message});
const at=s=>s.position.region==='alp'&&s.position.inside&&s.home.floor==='cellar';
export const ripeBatch=(s,b)=>s.day-b.madeDay>=3&&b.careDays.length>=3;
export function validDairy(d,day){const int=(n,a,b)=>Number.isSafeInteger(n)&&n>=a&&n<=b;if(!d||!int(d.nextId,1,1000000000)||!int(d.sold,0,1000000000)||!Array.isArray(d.batches)||d.batches.length>12||!d.batches.every(b=>b&&int(b.id,1,d.nextId-1)&&int(b.madeDay,1,day)&&Array.isArray(b.careDays)&&b.careDays.length<=3&&new Set(b.careDays).size===b.careDays.length&&b.careDays.every(n=>int(n,b.madeDay,day)))||new Set(d.batches.map(b=>b.id)).size!==d.batches.length)return false;if(d.active===null)return true;const a=d.active;return a&&DAIRY_STAGES.includes(a.stage)&&int(a.temperature,20,40)&&int(a.cuts,0,4)&&int(a.stirs,0,6)&&int(a.startedDay,1,day);}
export function startDairy(s,exchange){if(!at(s))return fail('Gehe ans Chessi in der Käsewerkstatt unter der Alphütte.');if(s.dairy.active)return fail('Deine aktuelle Käserunde wartet am Chessi.');if(s.dairy.batches.length>=12||s.dairy.nextId>=1000000000)return fail('Im Höhlenkeller ist kein Reifeplatz frei.');const r=exchange(s,{take:{milk:4,rennet:1,salt:1,wood:1},energy:5});if(!r.ok)return r;s.dairy.active={stage:'warm',temperature:20,cuts:0,stirs:0,startedDay:s.day};return{ok:true,message:'Milch, Lab, Salz und Holz bereitgestellt. Wärme die Milch vorsichtig auf.'};}
export function dairyStep(s,action){if(!at(s)||!s.dairy.active)return fail('Die Käserunde wartet in der Werkstatt.');const a=s.dairy.active;if(a.stage==='warm'){if(action==='heat'){a.temperature=Math.min(40,a.temperature+2);return{ok:true,message:'Milch: '+a.temperature+' °C · Zielbereich 30–34 °C.'};}if(action==='cool'){a.temperature=Math.max(20,a.temperature-2);return{ok:true,message:'Milch abkühlen lassen.'};}if(action!=='lab'||a.temperature<30||a.temperature>34)return fail('Für das Lab muss die Milch im grünen Bereich liegen: 30–34 °C.');a.stage='set';}
 else if(a.stage==='set'&&action==='wait')a.stage='cut';
 else if(a.stage==='cut'&&action==='cut'){a.cuts++;if(a.cuts===4)a.stage='stir';}
 else if(a.stage==='stir'&&action==='stir'){a.stirs++;if(a.stirs===6)a.stage='press';}
 else if(a.stage==='press'&&action==='press')a.stage='salt';
 else if(a.stage==='salt'&&action==='store'){if(s.dairy.batches.length>=12)return fail('Der Keller ist voll.');s.dairy.batches.push({id:s.dairy.nextId++,madeDay:s.day,careDays:[]});s.dairy.active=null;s.stats.crafts++;return{ok:true,message:'Gesalzen und eingelagert. Pflege den Laib an drei Spieltagen im Höhlenkeller.'};}
 else return fail('Dieser Arbeitsschritt ist noch nicht dran.');return{ok:true,message:'Arbeitsschritt gespeichert.'};}
export function careCheese(s,id,exchange){if(s.position.region!=='alp'||!s.position.inside||s.home.floor!=='cave')return fail('Gehe zuerst in den Höhlenkeller deiner Alp.');const b=s.dairy.batches.find(b=>b.id===id);if(!b)return fail('Dieser Laib ist nicht mehr im Keller.');if(ripeBatch(s,b)||b.careDays.length>=3)return fail('Dieser Laib ist ausreichend gepflegt.');if(b.careDays.includes(s.day))return fail('Heute bereits gewendet und geschmiert.');const r=exchange(s,{take:{water:1,salt:1},energy:2});if(!r.ok)return r;b.careDays.push(s.day);return{ok:true,message:'Laib '+id+' mit Salzwasser geschmiert und gewendet · '+b.careDays.length+' / 3 Pflegetage.'};}
export function collectCheese(s,id,exchange){if(s.position.region!=='alp'||!s.position.inside||s.home.floor!=='cave')return fail('Hole den Laib im Höhlenkeller ab.');const b=s.dairy.batches.find(b=>b.id===id);if(!b||!ripeBatch(s,b))return fail('Der Laib braucht mindestens drei Nächte und drei Pflegetage.');const r=exchange(s,{give:{caveCheese:1}});if(!r.ok)return r;s.dairy.batches=s.dairy.batches.filter(b=>b.id!==id);return{ok:true,message:'Höhlengereiften Portmann-Alpkäse eingepackt. Der Stadtladen kauft ihn für CHF 25.00 an.'};}
export function sellAlpProduct(s,id,exchange){if(s.position.region!=='city'||s.position.inside||Math.hypot(s.position.x-PORTMANN_STORE.x,s.position.z-PORTMANN_STORE.z)>PORTMANN_STORE.range)return fail('Gehe zum Portmann-Store in der Stadt.');const prices={caveCheese:2500,chocolate:650},price=prices[id];if(!price)return fail('Hier werden Portmann-Alpkäse und Alpschokolade angekauft.');const r=exchange(s,{take:{[id]:1},earn:price,stats:{earned:price,sales:1},reason:'sell',ref:id});if(!r.ok)return r;if(id==='caveCheese')s.dairy.sold++;return{ok:true,message:'Verkauft · CHF '+(price/100).toFixed(2)+' für deine nächsten Ausbauten.'};}
